L["The Shoulder Cam uses one of Blizzard's experimental camera settings. The game would warn about it every time you log in, so Cinematic keeps that warning away while the Shoulder Cam is on. If the camera ever acts up, turn the Shoulder Cam off and your own camera settings come back."] = "A Câmera de ombro usa uma das configurações de câmera experimentais da Blizzard. O jogo avisaria sobre isso toda vez que você entra, então o Cinematic mantém esse aviso longe enquanto a Câmera de ombro está ligada. Se a câmera se comportar estranho, desligue a Câmera de ombro e suas próprias configurações de câmera voltam."
L["Accept"] = "Aceitar"
L["Shoulder Cam is paused while the gamepad UI is on: the game keeps your character centered in it."] = "A Câmera de ombro fica pausada enquanto a interface de controle está ligada: o jogo mantém seu personagem centralizado nela."
