L["Stopped."] = "Parado."
L["Calibrate the Shoulder Cam for %s?\n\nIt says a line in /say a few times (everyone near you sees it), so somewhere quiet is best. Stand still on open, flat ground and leave the camera alone for about 10 seconds."] = "Calibrar a Câmera de ombro para %s?\n\nEla diz uma linha em /dizer algumas vezes (todos perto de você veem), então é melhor um lugar tranquilo. Fique parado em chão aberto e plano e deixe a câmera em paz por uns 10 segundos."
