L["Click to turn CineMode off."] = "Clique para desativar o CineMode."
L["Click to turn CineMode on."] = "Clique para ativar o CineMode."
L["Click to see why."] = "Clique para ver por quê."
L["CineMode is on"] = "O CineMode está ativado"
L["CineMode is off"] = "O CineMode está desativado"
L["Cameras (Camera tab) is set to CineMode."] = "Câmeras (aba Câmera) está configurado para o CineMode."
L["This page does nothing."] = "Esta página não faz nada."
L["Works while CineMode is on, and outside it while friendly nameplates show."] = "Funciona enquanto o CineMode está ativado, e fora dele enquanto as placas amistosas aparecem."
L["Works only while CineMode is on."] = "Só funciona enquanto o CineMode está ativado."
L["Works while CineMode is off too."] = "Funciona também com o CineMode desativado."
L["This page works as its settings say."] = "Esta página funciona como as configurações dela dizem."
L["Click to turn it on or off."] = "Clique para ativar ou desativar."
L["off with %s"] = "desativado com %s"
L["How fast the UI fades and what brings it back while CineMode is on."] = "A velocidade com que a interface esmaece e o que a traz de volta enquanto o CineMode está ativado."
L["How fast the UI fades, the Calm Timer, and fights coming in."] = "A velocidade com que a interface esmaece, o Cronômetro de calma e a chegada das lutas."
L["What takes you out of CineMode: fights, places, groups, moving and windows."] = "O que tira você do CineMode: lutas, lugares, grupos, movimento e janelas."
L["The minimap button, /cine hints, language and the menus' look."] = "O botão do minimapa, as dicas de /cine, o idioma e a aparência dos menus."
L["How long things take to fade in out of combat."] = "Quanto tempo as coisas levam para aparecer fora de combate."
L["How long things take to fade out."] = "Quanto tempo as coisas levam para esmaecer."
L["How long things take to fade in during a fight."] = "Quanto tempo as coisas levam para aparecer durante uma luta."
L["Casts count too when a rule uses Casting."] = "Lançamentos também contam quando uma regra usa Lançando."
L["As soon as a fight ends"] = "Assim que uma luta acaba"
L["How long after a fight before CineMode comes back."] = "Quanto tempo depois de uma luta até o CineMode voltar."
L["Ends the Calm Timer early once your health and power are back to full."] = "Encerra o Cronômetro de calma antes quando a sua vida e o seu poder voltam a ficar cheios."
L["With a pet out, its health must be full too."] = "Com um ajudante fora, a vida dele também precisa estar cheia."
L["Exit CineMode while an NPC window, like a quest giver or vendor, is open."] = "Sair do CineMode enquanto uma janela de PNJ, como a de um doador de missão ou vendedor, está aberta."
L["Exit CineMode while a game window, like your bags or the map, is open."] = "Sair do CineMode enquanto uma janela do jogo, como as bolsas ou o mapa, está aberta."
L["Picking up an item or spell brings the UI back until you put it down."] = "Pegar um item ou feitiço traz a interface de volta até você soltá-lo."
L["How long things must stay calm before CineMode comes back."] = "Quanto tempo as coisas precisam ficar calmas antes de o CineMode voltar."
L["Casting at an enemy out of combat brings up your combat frames."] = "Lançar num inimigo fora de combate traz os seus quadros de combate."
L["Being in combat brings the UI back."] = "Estar em combate traz a interface de volta."
L["In the open world"] = "No mundo aberto"
L["Anywhere outside cities, dungeons and raids."] = "Em qualquer lugar fora de cidades, masmorras e raides."
L["Capital cities, including Dalaran."] = "Capitais, incluindo Dalaran."
L["While you're flagged for PvP out in the world."] = "Enquanto você está marcado para JxJ no mundo."
L["In battlegrounds"] = "Em campos de batalha"
L["Battlegrounds and arenas."] = "Campos de batalha e arenas."
L["Back after stopping"] = "Voltar após parar"
L["CineMode comes back once you've stood still this long."] = "O CineMode volta quando você fica parado por este tempo."
L["Back after moving"] = "Voltar após se mover"
L["CineMode comes back once you've kept moving this long."] = "O CineMode volta quando você continua se movendo por este tempo."
L["Allow outside CineMode"] = "Permitir fora do CineMode"
L["CineMode hides your buffs and debuffs: pick what brings them back."] = "O CineMode oculta os seus bônus e penalidades: escolha o que os traz de volta."
L["Gaining or refreshing a buff briefly shows your buffs and debuffs."] = "Ganhar ou renovar um bônus mostra rapidamente os seus bônus e penalidades."
L["Lets this page bring your hidden buffs and debuffs back in CineMode."] = "Deixa esta página trazer de volta os seus bônus e penalidades ocultos no CineMode."
L["What brings your hidden buffs and debuffs up for a while."] = "O que traz os seus bônus e penalidades ocultos por um tempo."
L["Buffs you or your pet cast on yourself don't bring them up."] = "Bônus que você ou o seu ajudante lançam em vocês mesmos não os trazem."
L["Not while skyriding"] = "Não no voo dinâmico"
L["No buff brings them up while you're on a skyriding mount."] = "Nenhum bônus os traz enquanto você está numa montaria de voo dinâmico."
L["Only the buff you gained or refreshed shows."] = "Só o bônus que você ganhou ou renovou aparece."
L["Keep ones lasting less than up until they run out"] = "Manter os que duram menos que isto até acabarem"
L["A short buff stays up for as long as it lasts."] = "Um bônus curto fica visível enquanto durar."
L["Gaining or refreshing a debuff briefly shows your debuffs."] = "Ganhar ou renovar uma penalidade mostra rapidamente as suas penalidades."
L["Only within the Calm Timer after a fight."] = "Só dentro do Cronômetro de calma após uma luta."
L["Keeps them up while you have any debuff."] = "Mantém visíveis enquanto você tiver qualquer penalidade."
L["Debuffs that last longer than this don't bring them up."] = "Penalidades que duram mais que isto não as trazem."
L["Override Default Buff Reveal Time"] = "Substituir o tempo padrão dos bônus"
L["How long a new buff keeps the buffs up."] = "Quanto tempo um bônus novo mantém os bônus visíveis."
L["Override Default Debuff Reveal Time"] = "Substituir o tempo padrão das penalidades"
L["How long a new debuff keeps the buffs up."] = "Quanto tempo uma penalidade nova mantém os bônus visíveis."
L["Gaining this doesn't bring your buffs up; type a spell ID or name."] = "Ganhar isto não traz os seus bônus; digite um ID ou nome de feitiço."
L["Keeps drifting to new random distances after the first pull-back."] = "Continua flutuando para novas distâncias aleatórias depois do primeiro afastamento."
L["How much closer than your own zoom the random zoom may come."] = "O quanto o zoom aleatório pode chegar mais perto que o seu próprio zoom."
L["How much of each zoom is spent speeding up and slowing down."] = "Quanto de cada zoom é gasto acelerando e desacelerando."
L["Each pause varies at random by up to this much."] = "Cada pausa varia aleatoriamente até esta medida."
L["Raises the game's max camera distance while pulled back."] = "Aumenta a distância máxima de câmera do jogo enquanto afastada."
L["Lets the cameras start as the rows below say."] = "Deixa as câmeras começarem como as linhas abaixo dizem."
L["Top speed in the middle of a sweep."] = "Velocidade máxima no meio de uma varredura."
L["Each new angle is at least this many degrees from the last."] = "Cada novo ângulo fica pelo menos a esta quantidade de graus do anterior."
L["How far the camera may sway to either side."] = "O quanto a câmera pode balançar para cada lado."
L["Each move also tilts the camera to a random angle between these limits."] = "Cada movimento também inclina a câmera num ângulo aleatório entre estes limites."
L["The camera never tilts more than this far below where it started."] = "A câmera nunca se inclina mais que isto abaixo de onde começou."
L["How much of each move is spent speeding up and slowing down."] = "Quanto de cada movimento é gasto acelerando e desacelerando."
L["How long the camera rests between sweeps."] = "Quanto tempo a câmera descansa entre varreduras."
L["Puts this camera's settings back to your profile's values."] = "Volta as configurações desta câmera aos valores do seu perfil."
L["Runs this camera for 30 seconds where you stand."] = "Roda esta câmera por 30 segundos onde você está."
L["The camera slowly pulls back, then drifts in and out."] = "A câmera se afasta devagar e depois vai e vem."
L["After you move the camera yourself, it waits this long before carrying on."] = "Depois que você move a câmera, ela espera este tempo antes de continuar."
L["Doing the emote or pressing the sit key."] = "Fazer a expressão ou pressionar a tecla de sentar."
L["Clicking Sit, Kneel or Lie down on the campfire card, or its fire button (Emote Vision)."] = "Clicar em Sentar, Ajoelhar ou Deitar no cartão da fogueira, ou no botão de fogo dele (Emote Vision)."
L["Doing the emote, until you move or jump."] = "Fazer a expressão, até você se mover ou pular."
L["Right-clicking a seat to sit on it."] = "Clicar com o botão direito num assento para se sentar."
L["Unsheathing your weapon with your Sheathe key out of combat."] = "Desembainhar a arma com a tecla de embainhar fora de combate."
L["Casting your Hearthstone."] = "Usar a sua Pedra de Regresso."
L["Casting a teleport spell."] = "Lançar um feitiço de teleporte."
L["Logging out where the game counts down first."] = "Sair do jogo onde ele faz uma contagem regressiva antes."
L["Doing the emote while standing still."] = "Fazer a expressão parado."
L["Casting Fishing, until you move or jump."] = "Lançar Pesca, até você se mover ou pular."
L["Being flagged AFK."] = "Estar marcado como ausente."
L["Standing still for the time below with nothing else going on."] = "Ficar parado pelo tempo abaixo sem mais nada acontecendo."
L["Taking off on a flight path."] = "Decolar numa rota de voo."
L["Talking to a quest giver."] = "Falar com um doador de missão."
L["Talking to an NPC about a quest step."] = "Falar com um PNJ sobre uma etapa de missão."
L["On flight paths, the camera sways side to side with an occasional fly-by."] = "Nas rotas de voo, a câmera balança de um lado para o outro com um sobrevoo de vez em quando."
L["Your target's frames fade until you pick a new target or land."] = "Os quadros do seu alvo esmaecem até você escolher um alvo novo ou pousar."
L["Sway from side to side"] = "Balançar de um lado para o outro"
L["The camera sways from side to side around where it started."] = "A câmera balança de um lado para o outro em volta de onde começou."
L["Your character does /look as a fly-by starts, which players nearby see."] = "O seu personagem faz /look quando um sobrevoo começa, o que os jogadores por perto veem."
L["About one fly-by per this many seconds of flight."] = "Mais ou menos um sobrevoo a cada tantos segundos de voo."
L["Turn round"] = "Virar"
L["Turn back before landing"] = "Voltar antes de pousar"
L["Before you land, the camera turns back to where it was at takeoff."] = "Antes de você pousar, a câmera volta para onde estava na decolagem."
L["Turned back by"] = "Voltada até"
L["How long before landing the camera has settled."] = "Quanto tempo antes do pouso a câmera já se acomodou."
L["When you stand still a while or go AFK, the camera slowly circles your character."] = "Quando você fica parado um tempo ou fica ausente, a câmera circula devagar o seu personagem."
L["The camera sweeps around your character, pausing between sweeps."] = "A câmera varre em volta do seu personagem, pausando entre varreduras."
L["While you auto-run, the camera follows along until you stop or steer."] = "Enquanto você corre automaticamente, a câmera acompanha até você parar ou virar."
L["The camera eases out a little, then drifts in and out."] = "A câmera se afasta um pouco e depois vai e vem."
L["When you rest, sit or dance, the camera slowly turns to face you and eases in."] = "Quando você descansa, senta ou dança, a câmera vira devagar para encarar você e se aproxima."
L["How far the camera comes down toward the ground as it turns."] = "O quanto a câmera desce em direção ao chão enquanto vira."
L["The camera eases in close, then drifts a little in and out."] = "A câmera se aproxima e depois vai e vem um pouco."
L["The close-up distance the cozy camera zooms in to."] = "A distância de close-up até onde a câmera aconchegante se aproxima."
L["How much lower the camera sways, to look out across the view."] = "O quanto mais baixo a câmera balança, para olhar a paisagem."
L["The camera eases out a little, then drifts slowly in and out."] = "A câmera se afasta um pouco e depois vai e vem devagar."
L["The camera sways a little from side to side."] = "A câmera balança um pouco de um lado para o outro."
L["How much lower the camera sways, to look out across the water."] = "O quanto mais baixo a câmera balança, para olhar a água."
L["When you die, the camera slowly circles your body until you release or are revived."] = "Quando você morre, a câmera circula devagar o seu corpo até você liberar o espírito ou ser revivido."
L["If you die in a boss fight, the death camera waits for it to end."] = "Se você morrer numa luta contra chefe, a câmera de morte espera ela acabar."
L["No death camera when you can come back yourself, like with a soulstone."] = "Sem câmera de morte quando você pode voltar sozinho, como com uma pedra da alma."
L["Adds a button under the release popup to get your own view back."] = "Adiciona um botão abaixo do aviso de liberar espírito para ter a sua visão de volta."
L["How far the camera pulls back while you're dead."] = "O quanto a câmera se afasta enquanto você está morto."
L["How far the camera rises to look down on your body."] = "O quanto a câmera sobe para olhar o seu corpo de cima."
L["The groups ticked here stay up while the death camera hides your frames."] = "Os grupos marcados aqui ficam visíveis enquanto a câmera de morte oculta os seus quadros."
L["Music file IDs, separated by commas; one plays at random when you die."] = "IDs de arquivos de música, separados por vírgulas; um toca ao acaso quando você morre."
L["The camera turns toward NPCs as they talk near you."] = "A câmera vira para os PNJs quando eles falam perto de você."
L["The fastest the camera swings toward a new speaker."] = "O mais rápido que a câmera gira para quem começa a falar."
L["How far from the screen's center the speaker ends up."] = "A que distância do centro da tela quem fala acaba ficando."
L["How far the camera drifts side to side once settled."] = "O quanto a câmera flutua de lado depois de se acomodar."
L["The camera turns around to find speakers you can't see."] = "A câmera se vira para encontrar quem fala e você não vê."
L["Snaps to speakers, adds a tall letterbox with subtitles and fades the whole UI."] = "Salta para quem fala, adiciona faixas altas com legendas e esmaece a interface inteira."
L["How fast the camera zooms back out once the talking is over."] = "A velocidade com que a câmera volta a se afastar quando a conversa acaba."
L["The longest a zoom in or out can take."] = "O máximo que uma aproximação ou afastamento pode levar."
L["How long no one must talk before the camera turns back."] = "Quanto tempo sem ninguém falar até a câmera voltar."
L["When you talk to a quest giver, the camera zooms in and looks past you at them."] = "Quando você fala com um doador de missão, a câmera se aproxima e olha por cima de você para ele."
L["Also zooms in for NPCs with nothing to say about quests."] = "Também se aproxima de PNJs sem nada a dizer sobre missões."
L["The camera stays put when a quest giver only has dailies or weeklies."] = "A câmera fica parada quando um doador de missão só tem diárias ou semanais."
L["How far the camera turns to one side to look past you."] = "O quanto a câmera vira para um lado para olhar por cima de você."
L["How long the turn to the side takes."] = "Quanto tempo leva a virada para o lado."
L["How fast the camera zooms back out once you walk away."] = "A velocidade com que a câmera volta a se afastar quando você vai embora."
L["How far the camera comes down toward eye level."] = "O quanto a câmera desce até a altura dos olhos."
L["When you cast your Hearthstone or a teleport, the camera spins around you as it zooms in."] = "Quando você usa a Pedra de Regresso ou lança um teleporte, a câmera gira em volta de você enquanto se aproxima."
L["The distance the zoom ends at as the cast finishes."] = "A distância em que o zoom termina quando o lançamento acaba."
L["Canceling"] = "Cancelamento"
L["If you cancel the cast, the camera turns back to where it was."] = "Se você cancelar o lançamento, a câmera volta para onde estava."
L["Extra settings for cameras that aren't on the Scripts page yet."] = "Configurações extras de câmeras que ainda não estão na página Roteiros."
L["Mouse Turn"] = "Giro com o mouse"
L["Keeps right-mouse turning smooth by capping and easing its speed."] = "Mantém suave o giro com o botão direito, limitando e suavizando a velocidade."
L["Cap"] = "Limite"
L["Cap right-click turn speed"] = "Limitar velocidade do giro com botão direito"
L["Right-click turning never goes faster than the speed below."] = "O giro com o botão direito nunca passa da velocidade abaixo."
L["Top turn speed"] = "Velocidade máxima de giro"
L["The fastest you can turn."] = "O mais rápido que você pode virar."
L["Ease back over"] = "Voltar suavemente em"
L["How long your own Mouse Look Speed takes to come back after you slow down."] = "Quanto tempo a sua própria Velocidade de visão do mouse leva para voltar depois que você desacelera."
L["Ramp up right-click turn speed"] = "Acelerar aos poucos o giro com botão direito"
L["Each right-click turn starts slow and builds up to your own speed."] = "Cada giro com o botão direito começa devagar e vai até a sua velocidade."
L["Start at"] = "Começar em"
L["%d%% of your speed"] = "%d%% da sua velocidade"
L["How fast a turn starts, as a share of your own Mouse Look Speed."] = "A velocidade com que um giro começa, como parcela da sua própria Velocidade de visão do mouse."
L["Up to full speed over"] = "Até a velocidade total em"
L["How long a turn takes to build up to full speed."] = "Quanto tempo um giro leva para chegar à velocidade total."
L["Slow looking up and down too"] = "Desacelerar também olhar para cima e para baixo"
L["Looking up and down slows by the same share as turning."] = "Olhar para cima e para baixo desacelera na mesma parcela que o giro."
L["Turns the whole Atmosphere hub on or off at once."] = "Ativa ou desativa o grupo Atmosfera inteiro de uma vez."
L["How the game world looks in CineMode: vignette, inn glow, weather and depth of field."] = "Como o mundo do jogo fica no CineMode: vinheta, brilho de estalagem, clima e profundidade de campo."
L["Pick where and when each effect shows in CineMode."] = "Escolha onde e quando cada efeito aparece no CineMode."
L["Shows all the time in CineMode, fights included."] = "Aparece o tempo todo no CineMode, incluindo lutas."
L["Rain, snow and sandstorms tint the scene, more strongly in heavier weather."] = "Chuva, neve e tempestades de areia tingem a cena, com mais força quanto pior o tempo."
L["Reduce view distance in bad weather"] = "Reduzir distância de visão com mau tempo"
L["Brings the view distance in during rain, snow or sandstorms, more the heavier it gets."] = "Diminui a distância de visão durante chuva, neve ou tempestades de areia, mais quanto mais forte."
L["The game's graphics settings one by one, shared by every profile on this computer."] = "As configurações gráficas do jogo uma a uma, compartilhadas por todos os perfis neste computador."
L["Uses the settings below, or the game's own when turned off."] = "Usa as configurações abaixo, ou as do próprio jogo quando desativado."
L["World"] = "Mundo"
L["Ground clutter, view distance, detail and shadows."] = "Vegetação rasteira, distância de visão, detalhes e sombras."
L["Sky and water"] = "Céu e água"
L["Clouds, fog, reflections and ripples."] = "Nuvens, neblina, reflexos e ondulações."
L["Effects"] = "Efeitos"
L["Particles, glow, blood and sharpening."] = "Partículas, brilho, sangue e nitidez."
L["HDR"] = "HDR"
L["HDR output and brightness."] = "Saída HDR e brilho."
L["Nameplate distance and zoom distance."] = "Distância das placas e distância do zoom."
L["How far away grass and flowers start thinning out."] = "A que distância a grama e as flores começam a rarear."
L["How far the land is drawn in full; very demanding on frame rate."] = "Até onde o terreno é desenhado por completo; pesa muito na taxa de quadros."
L["How far away trees, rocks and other objects keep their full detail."] = "Até que distância árvores, pedras e outros objetos mantêm todo o detalhe."
L["How far away small objects stay before they fade out."] = "Até que distância objetos pequenos ficam antes de sumir."
L["How far away creatures and characters keep their full detail."] = "Até que distância criaturas e personagens mantêm todo o detalhe."
L["How far away nameplates show, in yards."] = "Até que distância as placas aparecem, em metros."
L["How far out you can zoom the camera."] = "O quanto você pode afastar a câmera."
L["Higher gives sharper shadow edges, lower saves frame rate."] = "Mais alto dá bordas de sombra mais nítidas, mais baixo poupa taxa de quadros."
L["Horizon distance"] = "Distância do horizonte"
L["How far the flat horizon past the land reaches."] = "Até onde vai o horizonte plano além do terreno."
L["Sky detail"] = "Detalhe do céu"
L["How detailed the clouds and sky are."] = "O nível de detalhe das nuvens e do céu."
L["Volumetric fog"] = "Neblina volumétrica"
L["Fog with depth in place of the usual distance fog."] = "Neblina com profundidade no lugar da neblina de distância comum."
L["Water reflections"] = "Reflexos na água"
L["How much of the world water reflects."] = "O quanto do mundo a água reflete."
L["Water ripples"] = "Ondulações na água"
L["How detailed the ripples on water are."] = "O nível de detalhe das ondulações na água."
L["Particle density"] = "Densidade de partículas"
L["How many particles spells and effects show."] = "Quantas partículas os feitiços e efeitos mostram."
L["Full-screen glow"] = "Brilho de tela cheia"
L["A soft glow around bright light."] = "Um brilho suave em volta de luzes fortes."
L["Gray screen on death"] = "Tela cinza ao morrer"
L["The world turns gray while you're dead."] = "O mundo fica cinza enquanto você está morto."
L["Blood and gore"] = "Sangue e violência"
L["How much blood shows in fights, from none to the most."] = "Quanto sangue aparece nas lutas, de nenhum ao máximo."
L["Always sharpen"] = "Sempre aplicar nitidez"
L["Sharpens the picture even at full render scale."] = "Aumenta a nitidez da imagem mesmo com a escala de renderização máxima."
L["HDR output"] = "Saída HDR"
L["Sends HDR to your monitor; Windows HDR must be on and Auto HDR off."] = "Envia HDR para o seu monitor; o HDR do Windows precisa estar ativado e o HDR automático desativado."
L["Use peak brightness"] = "Usar brilho de pico"
L["Peak brightness"] = "Brilho de pico"
L["Your monitor's peak brightness, in nits."] = "O brilho de pico do seu monitor, em nits."
L["HDR strength"] = "Intensidade do HDR"
L["How strong HDR is; works with peak brightness only."] = "A intensidade do HDR; só funciona com o brilho de pico."
L["Use reference brightness"] = "Usar brilho de referência"
L["Reference brightness"] = "Brilho de referência"
L["How bright white looks in HDR, in nits."] = "O brilho do branco no HDR, em nits."
L["Sky and weather"] = "Céu e clima"
L["Water"] = "Água"
L["Restart graphics"] = "Reiniciar gráficos"
L["Restarts the game's graphics without leaving the game; the screen goes black for a moment."] = "Reinicia os gráficos do jogo sem sair dele; a tela fica preta por um momento."
L["Sound and music during CineMode; your own sound settings come back afterward."] = "Som e música durante o CineMode; as suas configurações de som voltam depois."
L["Plays music when a camera starts in CineMode and fades it out when the UI returns."] = "Toca música quando uma câmera começa no CineMode e a esmaece quando a interface volta."
L["Pick where and when music can play in CineMode."] = "Escolha onde e quando a música pode tocar no CineMode."
L["After a camera starts music, no camera starts it again for this long."] = "Depois que uma câmera inicia a música, nenhuma câmera a inicia de novo por este tempo."
L["Fades music out once you leave the camera modes and move on."] = "Esmaece a música quando você sai dos modos de câmera e segue em frente."
L["Each row is a scene that plays its camera when one of its triggers happens."] = "Cada linha é uma cena que toca a câmera dela quando um dos gatilhos dela acontece."
L["Lets the scenes below play their cameras when their triggers happen."] = "Deixa as cenas abaixo tocarem as câmeras delas quando os gatilhos delas acontecem."
L["Auto-running in walk mode."] = "Correr automaticamente no modo andar."
L["Auto-running."] = "Correr automaticamente."
L["Dying, until you release or are resurrected."] = "Morrer, até você liberar o espírito ou ser ressuscitado."
L["An NPC talking to you or your party; the camera swings toward whoever's talking."] = "Um PNJ falando com você ou com o seu grupo; a câmera gira para quem está falando."
L["Other NPCs talking near you, once you've stood still a while."] = "Outros PNJs falando perto de você, depois de você ficar parado um tempo."
L["Starts music as this camera starts; needs the Audio page on."] = "Inicia música quando esta câmera começa; precisa da página Áudio ativada."
L["Plays a song of its own while the death camera runs."] = "Toca uma música própria enquanto a câmera de morte roda."
L["Brings CineMode on while this camera runs, when Start in CineMode is off."] = "Ativa o CineMode enquanto esta câmera roda, quando Começar no CineMode está desativado."
L["Buff names or spell IDs, separated by commas."] = "Nomes de bônus ou IDs de feitiço, separados por vírgulas."
L["Words in an object's name that mark it as a seat, separated by commas."] = "Palavras no nome de um objeto que o marcam como assento, separadas por vírgulas."
L["How long you stand still before this row's camera starts."] = "Quanto tempo você fica parado antes de a câmera desta linha começar."
L["How long the camera waits on a quest window before it starts."] = "Quanto tempo a câmera espera numa janela de missão antes de começar."
L["How long the camera waits on the window before it starts."] = "Quanto tempo a câmera espera na janela antes de começar."
L["How long you stand still before NPCs chatting nearby start this camera."] = "Quanto tempo você fica parado antes de PNJs conversando por perto iniciarem esta câmera."
L["How long you keep going before this row's camera starts."] = "Quanto tempo você continua antes de a câmera desta linha começar."
L["Whether this row's camera may start in or after a fight."] = "Se a câmera desta linha pode começar durante ou depois de uma luta."
L["Where this row's camera may start."] = "Onde a câmera desta linha pode começar."
L["Pause cameras while a window is open"] = "Pausar câmeras com uma janela aberta"
L["Scenes pause while a window like the map or spellbook is open."] = "As cenas pausam enquanto uma janela como o mapa ou o grimório está aberta."
L["Lists the rows by camera name or by scene name."] = "Lista as linhas pelo nome da câmera ou pelo nome da cena."
L["Make a scene of your own with its triggers, camera and end."] = "Crie uma cena sua com gatilhos, câmera e fim."
L["A scene of your own; open it to set its triggers and when it ends."] = "Uma cena sua; abra-a para definir os gatilhos e quando ela termina."
L["Copies this row just below, so you can give it another camera."] = "Copia esta linha logo abaixo, para você dar outra câmera a ela."
L["Deletes this scene so it starts no camera."] = "Exclui esta cena para ela não iniciar nenhuma câmera."
L["Your own name for this row, shown on the grid."] = "Um nome seu para esta linha, mostrado na grade."
L["The camera this row starts."] = "A câmera que esta linha inicia."
L["This row's camera may start anywhere."] = "A câmera desta linha pode começar em qualquer lugar."
L["Indoors, the camera modes zoom out and swing less so they don't hit walls."] = "Em ambientes fechados, os modos de câmera se afastam e giram menos para não bater nas paredes."
L["How far past your own distance the slow zoom may pull back indoors."] = "O quanto além da sua distância o zoom lento pode se afastar em ambientes fechados."
L["Stops the AFK camera sweeping around you indoors, where it can hit walls."] = "Impede a câmera LDT de girar em volta de você em ambientes fechados, onde ela pode bater nas paredes."
L["Shows it whenever its frame shows, hovered or not."] = "Mostra sempre que o quadro dele aparece, com o mouse em cima ou não."
L["Shows it the whole time, CineMode or not."] = "Mostra o tempo todo, com ou sem CineMode."
L["CineMode hides everything: pick which frames show, and when."] = "O CineMode oculta tudo: escolha quais quadros aparecem, e quando."
L["CineMode hides everything: tick which frames show, and when."] = "O CineMode oculta tudo: marque quais quadros aparecem, e quando."
L["CineMode hides these frames, and shows them only when their rows say."] = "O CineMode oculta estes quadros e só os mostra quando as linhas deles mandam."
L["CineMode hides the frames in this section, and shows them only when their rows say."] = "O CineMode oculta os quadros desta seção e só os mostra quando as linhas deles mandam."
L["Not in use"] = "Fora de uso"
L["Shows or hides its parts."] = "Mostra ou oculta as partes dele."
L["Shows the same parts as the Target rows."] = "Mostra as mesmas partes que as linhas do Alvo."
L["Raid-style party frames follow the Raid tab's rows."] = "Os quadros de grupo estilo raide seguem as linhas da aba Raide."
L["Same as"] = "Igual a"
