L["Opens the Raid tab."] = "Abre a aba Raide."
L["Your Edit Mode layout has Use Raid-Style Party Frames ticked."] = "O seu layout do Modo de Edição está com Usar quadros de grupo estilo raide marcado."
L["Your Edit Mode layout has Use Raid-Style Party Frames unticked."] = "O seu layout do Modo de Edição está com Usar quadros de grupo estilo raide desmarcado."
L["Hide keybinds"] = "Ocultar atalhos"
L["Hides the key names on the action bar buttons (1, a-Q, s-2...), CineMode or not."] = "Oculta os nomes das teclas nos botões das barras de ações (1, a-Q, s-2...), com ou sem CineMode."
L["Hide macro names"] = "Ocultar nomes de macros"
L["Hides the macro names on the action bar buttons, CineMode or not."] = "Oculta os nomes de macros nos botões das barras de ações, com ou sem CineMode."
L["Show while the spellbook is open"] = "Mostrar com o grimório aberto"
L["Keeps your action bars up while the spellbook or macros window is open."] = "Mantém as suas barras de ações visíveis enquanto o grimório ou a janela de macros está aberto."
