L["CineMode hides your swing timer: pick when it shows."] = "O CineMode oculta o seu cronômetro de golpes: escolha quando ele aparece."
L["CineMode hides the chat window: pick when it shows."] = "O CineMode oculta a janela de bate-papo: escolha quando ela aparece."
L["CineMode hides info frames and menus: pick which show, and when."] = "O CineMode oculta quadros de informação e menus: escolha quais aparecem, e quando."
L["CineMode hides the minimap: pick which parts show, and when."] = "O CineMode oculta o minimapa: escolha quais partes aparecem, e quando."
L["CineMode hides the quest tracker: pick when it shows."] = "O CineMode oculta o rastreador de missões: escolha quando ele aparece."
L["CineMode hides the party frames: pick when they show."] = "O CineMode oculta os quadros de grupo: escolha quando eles aparecem."
L["CineMode hides the raid frames: pick when they show."] = "O CineMode oculta os quadros de raide: escolha quando eles aparecem."
L["CineMode hides the raid-style party frames: pick when they show."] = "O CineMode oculta os quadros de grupo estilo raide: escolha quando eles aparecem."
L["CineMode hides your character's highlight: pick when it shows."] = "O CineMode oculta o destaque do seu personagem: escolha quando ele aparece."
L["CineMode hides these frames: pick which show, and when."] = "O CineMode oculta estes quadros: escolha quais aparecem, e quando."
L["Pick where chat bubbles show."] = "Escolha onde os balões de fala aparecem."
L["Pick where and when each kind of bubble shows."] = "Escolha onde e quando cada tipo de balão aparece."
L["These bubbles show everywhere, in fights and out."] = "Estes balões aparecem em todo lugar, em combate e fora dele."
L["Cinematic draws its own bubbles for speech whose game bubble you can't see."] = "O Cinematic desenha balões próprios para falas cujo balão do jogo você não consegue ver."
L["Shows speech from someone off screen in a bubble low on the screen."] = "Mostra a fala de alguém fora da tela num balão na parte de baixo da tela."
L["Opens the Chat Bubble Style page: how off-screen bubbles look and where they show."] = "Abre a página Estilo dos balões de fala: a aparência dos balões de fora da tela e onde eles aparecem."
L["Shows emotes in the off-screen bubbles too, instead of in chat."] = "Mostra as expressões também nos balões de fora da tela, em vez de no bate-papo."
L["Moves bubbles at the very top of the screen down where you can read them."] = "Desce os balões que estão bem no topo da tela para onde você consegue lê-los."
L["Small helpers for getting around the world."] = "Pequenas ajudas para se virar pelo mundo."
L["Turns all the Quality of Life helpers on or off."] = "Ativa ou desativa todas as ajudas de Qualidade de vida."
L["Opens the character window when you drag gear out of your bags."] = "Abre a janela do personagem quando você arrasta um equipamento para fora das bolsas."
L["Adds a button to view the talents of someone you inspect."] = "Adiciona um botão para ver os talentos de quem você inspecionar."
L["Adds a talent calculator button to your talents window to plan a build."] = "Adiciona um botão de calculadora de talentos à sua janela de talentos para planejar uma build."
L["Moves game windows away from the left edge so your character stays in view."] = "Afasta as janelas do jogo da borda esquerda para o seu personagem continuar à vista."
L["Lets you drag the game's windows to move them."] = "Deixa você arrastar as janelas do jogo para movê-las."
L["Adds an icon to chat windows to copy their text."] = "Adiciona um ícone às janelas de bate-papo para copiar o texto delas."
L["Keep chat history"] = "Manter histórico do bate-papo"
L["Chat windows bring back their last lines after a reload or login."] = "As janelas de bate-papo trazem de volta as últimas linhas depois de recarregar ou entrar no jogo."
L["Show the time on those lines"] = "Mostrar a hora nessas linhas"
L["Puts the time at the start of brought-back lines."] = "Coloca a hora no início das linhas recuperadas."
L["Show XP left to level"] = "Mostrar XP que falta para o nível"
L["Shows how much XP you still need for the next level."] = "Mostra quanto XP você ainda precisa para o próximo nível."
L["The camera zooms to the distance below when you log in or reload."] = "A câmera vai até a distância abaixo quando você entra no jogo ou recarrega."
L["The camera distance to start at."] = "A distância de câmera inicial."
L["A button at the top of the screen that reloads the UI in one click."] = "Um botão no topo da tela que recarrega a interface com um clique."
L["Reopens the windows you had open after a reload."] = "Reabre as janelas que você tinha abertas depois de recarregar."
L["Hides floating damage and healing numbers in CineMode out of combat."] = "Oculta os números flutuantes de dano e cura no CineMode fora de combate."
L["Hides the red error text while you're fighting."] = "Oculta o texto de erro vermelho enquanto você luta."
L["Hides the red error text while you're out of combat."] = "Oculta o texto de erro vermelho enquanto você está fora de combate."
L["Turns the Hunter helpers on or off."] = "Ativa ou desativa as ajudas de Caçador."
L["Right-clicking an enemy uses Auto Shot when it's far enough away."] = "Clicar com o botão direito num inimigo usa Tiro Automático quando ele está longe o bastante."
L["Moves the smallest ammo stack first after Clean Up Bags, so it's shot first."] = "Move a menor pilha de munição para a frente depois de Organizar Bolsas, para ela ser disparada primeiro."
L["Adds a Fill button at vendors that fills your quiver with ammo."] = "Adiciona um botão Encher nos vendedores que enche a sua aljava de munição."
L["Keeps your pet frame up while your pet isn't happy."] = "Mantém o quadro do ajudante visível enquanto o seu ajudante não está feliz."
L["The pet frame fades with the UI while a camera mode runs."] = "O quadro do ajudante esmaece com a interface enquanto um modo de câmera roda."
L["Move Questie's nameplate icons"] = "Mover os ícones de placa do Questie"
L["Moves Questie's quest icons beside the name, where Cinematic's quest mark goes."] = "Move os ícones de missão do Questie para o lado do nome, onde fica a marca de missão do Cinematic."
L["Move EnhanceQoL's nameplate quest marks"] = "Mover as marcas de missão de placa do EnhanceQoL"
