L["Popup location"] = "Posição do aviso"
L["How many items the window shows at once; the oldest goes when a new one drops."] = "Quantos itens a janela mostra de uma vez; o mais antigo sai quando um novo cai."
L["Always show your roll"] = "Sempre mostrar a sua rolagem"
L["Your own roll always shows on an item's panel."] = "A sua própria rolagem sempre aparece no painel de um item."
L["Always show rolls I need"] = "Sempre mostrar rolagens em que rolo Necessidade"
L["Items you roll Need on always show everyone's rolls."] = "Os itens em que você rola Necessidade sempre mostram as rolagens de todos."
L["Shows the extra lines under an item's players, like who passed, in a party, raid or both."] = "Mostra as linhas extras sob os jogadores de um item, como quem passou, em grupo, raide ou ambos."
L["Show selected count"] = "Mostrar contagem de escolhas"
L["Stays hidden while another addon handles loot rolls."] = "Fica oculto enquanto outro addon cuida das rolagens de saque."
L["In CineMode, shows the nameplates of players dueling near you so you can watch."] = "No CineMode, mostra as placas dos jogadores duelando perto de você para você assistir."
L["Shows an icon beside a duelist's nameplate while they're crowd controlled."] = "Mostra um ícone ao lado da placa de um duelista enquanto ele está sob controle de grupo."
L["Instant spells"] = "Feitiços instantâneos"
L["Shows a duelist's instant spells as icons beside their nameplate."] = "Mostra os feitiços instantâneos de um duelista como ícones ao lado da placa dele."
L["Spell names"] = "Nomes dos feitiços"
L["The newest instant spell's name shows above its icon."] = "O nome do feitiço instantâneo mais recente aparece acima do ícone dele."
L["Hides other players' duels while you're in one."] = "Oculta os duelos de outros jogadores enquanto você está em um."
L["Shows a 30-second pretend duel between nearby players so you can see how it looks."] = "Mostra um duelo de mentira de 30 segundos entre jogadores próximos para você ver como fica."
