-- Changelog.lua
L["A button on the main page puts Cinematic back to a fresh install."] = "Um botão na página principal volta o Cinematic ao estado de recém-instalado."
L["A fishing camera and settings of its own."] = "Uma câmera de pesca com configurações próprias."
